+  min-width: 0;
+}
+.budget-overview-heading,
+.budget-overview-missions li > header {
+  display: flex;
+  align-items: flex-start;
+  justify-content: space-between;
+  gap: 1rem;
+  flex-wrap: wrap;
+}
+.budget-overview h2,
+.budget-overview h3 { margin-block: 0.25rem; }
+.budget-overview p { max-width: 100ch; line-height: 1.55; }
+.budget-overview-scope,
+.budget-overview-boundary { font-size: 0.85rem; }
+.budget-overview-metrics {
+  display: grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: 0.75rem;
+  margin-block: 1rem;
+}
+.budget-overview-metrics > div {
+  padding: 0.75rem;
+  border: 1px solid currentColor;
+  border-radius: 0.5rem;
+  min-width: 0;
+}
+.budget-overview-metrics dt { font-size: 0.75rem; }
+.budget-overview-metrics dd { margin: 0.4rem 0 0; }
+.budget-overview-metrics dd > * { display: block; overflow-wrap: anywhere; }
+.budget-overview-metrics dd > span { margin-top: 0.3rem; }
+.budget-overview-metrics small { font-size: 0.7rem; }
+.budget-overview-notice {
+  padding: 0.65rem 0.8rem;
+  border-inline-start: 3px solid currentColor;
+  font-size: 0.85rem;
+}
+.budget-overview-attention { margin-block: 1rem; }
+.budget-overview-attention ul,
+.budget-overview-missions > ul { padding: 0; list-style: none; }
+.budget-overview-attention li { margin-block: 0.6rem; }
+.budget-overview-attention li > span { display: block; font-size: 0.8rem; margin-top: 0.4rem; }
+.budget-overview-missions > ul > li { border-top: 1px solid currentColor; padding-block: 1rem; }
+.budget-overview-missions summary { cursor: pointer; padding-block: 0.65rem; font-weight: 600; }
+.budget-overview-links { display: flex; flex-wrap: wrap; gap: 0.5rem; }
+.budget-overview button { max-width: 100%; white-space: normal; overflow-wrap: anywhere; text-align: start; }
+.budget-overview button:focus-visible,
+.budget-overview summary:focus-visible { outline: 2px solid currentColor; outline-offset: 3px; }
+@media (max-width: 800px) {
+  .budget-overview-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
+}
+@media (max-width: 440px) {
+  .budget-overview-metrics { grid-template-columns: minmax(0, 1fr); }
+  .budget-overview-heading > button,
+  .budget-overview-links > button { width: 100%; }
+}
diff --git a/apps/web/src/BudgetOverviewPanel.test.mjs b/apps/web/src/BudgetOverviewPanel.test.mjs
