+++ b/apps/web/src/BudgetOverviewPanel.test.mjs
@@ -0,0 +1,203 @@
+import assert from 'node:assert/strict'
+import test from 'node:test'
+import { readFile } from 'node:fs/promises'
+import * as React from 'react'
+import * as jsxRuntime from 'react/jsx-runtime'
+import { renderToStaticMarkup } from 'react-dom/server'
+import ts from 'typescript'
+import * as budget from './budgetOverview.ts'
+import { elements, renderHooks } from './testSupport/renderHooks.mjs'
+
+const source = await readFile(new URL('./BudgetOverviewPanel.tsx', import.meta.url), 'utf8')
+const compiled = ts.transpileModule(source, { fileName: 'BudgetOverviewPanel.tsx', reportDiagnostics: true,
+  compilerOptions: { target: ts.ScriptTarget.ES2023, module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.ReactJSX } })
+assert.deepEqual(compiled.diagnostics, [])
+function loadPanel(react) {
+  const exports = {}
+  new Function('require', 'exports', compiled.outputText)((name) => {
+    const imports = { react, 'react/jsx-runtime': jsxRuntime, './budgetOverview': budget, './BudgetOverviewPanel.css': {} }
+    if (!(name in imports)) throw new Error(`Unexpected dependency ${name}`)
+    return imports[name]
+  }, exports)
+  return exports.BudgetOverviewPanel
+}
+const BudgetOverviewPanel = loadPanel(React)
+
+function fixture() {
+  return {
+    snapshot: {
+      corp: { id: 'corp-a', name: 'Authorized Corp' },
+      rooms: [{ id: 'room-a', corp_id: 'corp-a' }],
+      missions: [{ id: 'mission-a', corp_id: 'corp-a', room_id: 'room-a', title: 'Scoped mission', status: 'running',
+        original_budget_tokens: 1000, original_budget_cost_microusd: 1_000_000,
+        budget_tokens: 2000, budget_cost_microusd: 2_000_000 }],
+      tasks: [{ id: 'task-a', corp_id: 'corp-a', mission_id: 'mission-a', attempt_count: 1 }],
+      runs: [{ id: 'run-a', corp_id: 'corp-a', task_id: 'task-a', agent_id: 'worker-a', status: 'cancelled',
+        breaker_stage: 'suspend', resumed_from_run_id: null, input_tokens: 100, output_tokens: 10, cost_microusd: 0 }],
+      mission_budget_revisions: [{ id: 'revision-a', corp_id: 'corp-a', mission_id: 'mission-a', status: 'pending', version: 2,
+        proposed_budget_tokens: 3000, proposed_budget_cost_microusd: 3_000_000 }],
+    },
+    viewer: { corpId: 'corp-a', actorId: 'alice' },
+    stamp: { corpId: 'corp-a', actorId: 'alice', receivedAt: new Date().toISOString(), connection: 'live', refreshFailed: false },
+    onRefresh() {}, onOpen() {},
+  }
+}
+const render = (props) => renderToStaticMarkup(jsxRuntime.jsx(BudgetOverviewPanel, props))
+
+test('renders actual snapshot totals and limitations with pending decisions outside the disclosure', () => {
+  const html = render(fixture())
+  const summary = html.split('<details')[0]
+  assert.match(summary, /Snapshot-limited totals/)
+  assert.match(summary, /No time filter; includes completed work returned in this snapshot/)
+  assert.match(summary, /not a shared pool or permission to spend/)
+  assert.match(summary, /1,000 tokens/)
+  assert.match(summary, /2,000 tokens/)
+  assert.match(summary, /110 tokens/)
+  assert.match(summary, /1,890 tokens/)
+  assert.match(summary, /1 budget requests need a decision/)
+  assert.match(summary, /Scoped mission · inspect pending revision 2/)
+  assert.match(summary, /3,000 tokens · \$3.00. Not yet authorized/)
+  assert.match(summary, /Measured and estimated cost are unavailable/)
+  assert.match(summary, /1 runs have unpriced token usage/)
+  assert.match(summary, /Zero reported cost is not evidence of free work/)
+  assert.match(summary, /remainder may overstate headroom/)
+  assert.match(summary, /Auditor-led extension and audit status are unavailable/)
+  assert.match(summary, /1 revised mission ceilings have no matching approval receipt/)
+  assert.match(html, /Inspect suspension run-a &amp; existing recovery controls/)
+  assert.doesNotMatch(html, /<details[^>]*\bopen/)
+})
+
+for (const [name, change] of [
+  ['revoked refresh', (props) => { props.stamp.refreshFailed = true }],
+  ['changed actor', (props) => { props.viewer.actorId = 'bob' }],
+  ['changed Corp', (props) => { props.viewer.corpId = 'corp-b' }],
+  ['offline', (props) => { props.stamp.connection = 'offline' }],
+  ['old receipt', (props) => { props.stamp.receivedAt = '2000-01-01T00:00:00Z' }],
+  ['missing receipt', (props) => { props.stamp.receivedAt = null }],
+]) test(`${name} renders a refreshable state with no prior titles, spend or decision links`, () => {
+  const props = fixture()
+  change(props)
+  const html = render(props)
+  assert.match(html, /role="status"/)
+  assert.match(html, /Refresh budgets/)
+  assert.doesNotMatch(html, /Scoped mission|Authorized Corp|budget-overview-totals|revision-a|2,000 tokens/)
+})
+
+test('empty authorized data differs from a failed read', () => {
+  const props = fixture()
+  for (const key of ['missions', 'tasks', 'runs', 'mission_budget_revisions']) props.snapshot[key] = []
+  const html = render(props)
+  assert.match(html, /No missions are available in this authorized snapshot/)
+  assert.match(html, /0 tokens/)
+  assert.match(html, /\$0.00/)
+  assert.doesNotMatch(html, /role="status"/)
+})
+
+test('missing history and invalid requested amounts stay explicit without crashing the component', () => {
+  const props = fixture()
+  props.snapshot.tasks[0].attempt_count = 2
+  props.snapshot.mission_budget_revisions[0].proposed_budget_tokens = NaN
+  props.snapshot.mission_budget_revisions[0].proposed_budget_cost_microusd = 0.1
+  const html = render(props)
+  assert.match(html.split('<details')[0], /Some usage or run history is missing or invalid/)
+  assert.match(html, /Requested: Unavailable · Unavailable. Not yet authorized/)
+  assert.match(html, /recorded subtotal is not proof of total consumption/)
+})
+
+test('mission labels use React escaping and never introduce executable markup', () => {
+  const props = fixture()
+  props.snapshot.missions[0].title = '<script>alert("not markup")</script>'
+  const html = render(props)
+  assert.match(html, /&lt;script&gt;/)
+  assert.doesNotMatch(html, /<script\b/)
+})
+
+function clockFixture(t) {
+  const hooks = renderHooks(), panel = loadPanel(hooks.react), timers = new Map()
+  let now = Date.parse('2026-09-29T12:00:00Z'), id = 0, props = fixture()
+  const calls = { opened: [], refreshed: 0 }
+  props.stamp.receivedAt = new Date(now).toISOString()
+  props.onOpen = (target) => calls.opened.push(target)
+  props.onRefresh = () => { calls.refreshed++ }
+  t.mock.method(Date, 'now', () => now)
+  const original = globalThis.window
+  globalThis.window = {
+    setTimeout(callback, delay) { timers.set(++id, { at: now + delay, callback }); return id },
+    clearTimeout(key) { timers.delete(key) },
+  }
+  t.after(() => {
+    hooks.unmount()
+    assert.equal(timers.size, 0, 'Unmount releases every owned timer')
+    if (original === undefined) delete globalThis.window
+    else globalThis.window = original
+  })
+  return {
+    hooks, calls, timers,
+    get now() { return now },
+    set now(value) { now = value },
+    get props() { return props },
+    replace(next) { props = next; return hooks.begin(() => panel(props)) },
+    render() { return hooks.render(() => panel(props)) },
+    due() {
+      for (const [key, timer] of [...timers]) if (timer.at <= now) {
+        timers.delete(key); timer.callback()
+      }
+      return hooks.flush()
+    },
+  }
+}
+const hasTotals = (tree) => elements(tree, (node) => node.props?.['data-testid'] === 'budget-overview-totals').length > 0
+const openBudget = (tree) => elements(tree, (node) => node.type === 'button' && node.props.children === 'Open mission budget')[0].props.onClick()
+
+test('clock expiry hides totals without polling and navigation rechecks a delayed timer', (t) => {
+  const c = clockFixture(t)
+  const initial = c.render()
+  assert.equal(hasTotals(initial), true)
+  c.due()
+  openBudget(initial)
+  assert.equal(c.calls.opened.length, 1)
+  c.now += budget.BUDGET_SNAPSHOT_FRESH_MS
+  openBudget(initial) // The browser may throttle the scheduled expiration callback.
+  assert.equal(c.calls.opened.length, 1)
+  assert.equal(c.calls.refreshed, 1)
+  c.now++
+  assert.equal(hasTotals(c.due()), false)
+  assert.equal(c.timers.size, 0, 'A spent snapshot does not schedule repeated clock work')
+})
+
+test('a fresh receipt cancels prior expiration and access loss hides data before effects', (t) => {
+  const c = clockFixture(t)
+  c.render(); c.due()
+  c.now += 30_000
+  c.replace({ ...c.props, stamp: { ...c.props.stamp, receivedAt: new Date(c.now).toISOString() } })
+  assert.equal(hasTotals(c.hooks.flushLayout()), true, 'Fresh totals are present before passive effects or timers')
+  c.hooks.flush(); c.due()
+  assert.equal(hasTotals(c.hooks.value), true)
+  c.now += 30_002
+  assert.equal(hasTotals(c.due()), true, 'The superseded receipt cannot expire the current data')
+  const denied = c.replace({ ...c.props, stamp: { ...c.props.stamp, refreshFailed: true } })
+  assert.equal(hasTotals(denied), false, 'A denied refresh removes amounts during render')
+  c.hooks.flush()
+  const otherViewer = c.replace({ ...c.props, viewer: { corpId: 'corp-a', actorId: 'bob' } })
+  assert.equal(hasTotals(otherViewer), false)
+})
+
+test('receipt synchronization does not make a genuinely future receipt current', (t) => {
+  const c = clockFixture(t)
+  c.render()
+  c.now += 30_000
+  c.replace({ ...c.props, stamp: { ...c.props.stamp, receivedAt: new Date(c.now + 120_000).toISOString() } })
+  assert.equal(hasTotals(c.hooks.flushLayout()), false)
+  assert.equal(hasTotals(c.due()), false)
+})
+
+test('StrictMode effect replay owns one receipt sample and expiry with no leaked timer', (t) => {
+  const c = clockFixture(t)
+  c.render()
+  c.hooks.replayEffects()
+  c.hooks.replayEffects()
+  c.due()
+  c.now += budget.BUDGET_SNAPSHOT_FRESH_MS + 1
+  assert.equal(hasTotals(c.due()), false)
+  assert.equal(c.timers.size, 0)
+})
diff --git a/apps/web/src/BudgetOverviewPanel.tsx b/apps/web/src/BudgetOverviewPanel.tsx
new file mode 100644
index 00000000..4cbb045a
--- /dev/null
+++ b/apps/web/src/BudgetOverviewPanel.tsx
@@ -0,0 +1,121 @@
+import { useCallback, useLayoutEffect, useState } from 'react'
+import {
+  BUDGET_SNAPSHOT_FRESH_MS, budgetAuthority, budgetDestinationAvailable, buildBudgetOverview,
+  formatBudgetMoney, formatBudgetTokens,
+} from './budgetOverview'
+import type { BudgetDestination, BudgetRow, BudgetSnapshot, BudgetSnapshotStamp, BudgetViewer } from './budgetOverview'
+import './BudgetOverviewPanel.css'
+
+type Props = {
+  snapshot: BudgetSnapshot
+  viewer: BudgetViewer
+  stamp: BudgetSnapshotStamp
+  onRefresh: () => void
+  onOpen: (target: BudgetDestination) => void
+}
+
+function AuthorityValues({ label, value, costLabel }: {
+  label: string; value: BudgetRow['original']; costLabel: string
+}) {
+  return <div><dt>{label}</dt><dd><strong>{formatBudgetTokens(value.tokens)}</strong>
+    <span>{formatBudgetMoney(value.cost)} <small>{costLabel}</small></span></dd></div>
+}
+
+export function BudgetOverviewPanel({ snapshot, viewer, stamp, onRefresh, onOpen }: Props) {
+  const [now, updateClock] = useState(Date.now)
+  useLayoutEffect(() => {
+    const current = Date.now()
+    // Sample before paint so a new receipt is not compared with the prior
+    // receipt's clock. Future timestamps still fail against the actual clock.
+    // oxlint-disable-next-line react/set-state-in-effect
+    updateClock(current)
+    const delay = Date.parse(stamp.receivedAt ?? '') + BUDGET_SNAPSHOT_FRESH_MS - current
+    const expiry = Number.isFinite(delay) && delay > 0
+      ? window.setTimeout(() => updateClock(Date.now()), delay + 1) : undefined
+    return () => { window.clearTimeout(expiry) }
+  }, [stamp.receivedAt])
+  const overview = buildBudgetOverview(snapshot, viewer, stamp, now)
+  const totals = overview.totals
+  const pending = overview.rows.flatMap((row) => row.pending.map((revision) => ({ row, revision })))
+  const suspended = overview.rows.filter((row) => row.suspendedRunIds.length)
+  const unpriced = overview.rows.reduce((total, row) => total + row.unpricedRuns, 0)
+  const unreported = overview.rows.reduce((total, row) => total + row.unreportedRuns, 0)
+  const incomplete = overview.rows.some((row) => row.missingHistory || row.invalidUsage) || overview.unattributedRuns > 0
+  const missingDecisions = overview.rows.filter((row) => row.currentDecisionMissing).length
+  const open = useCallback((target: BudgetDestination) => {
+    if (budgetDestinationAvailable(buildBudgetOverview(snapshot, viewer, stamp, Date.now()), target)) onOpen(target)
+    else onRefresh()
+  }, [snapshot, viewer, stamp, onOpen, onRefresh])
+
+  return <section className="budget-overview panel" aria-labelledby="budget-overview-title" data-testid="budget-overview">
+    <header className="budget-overview-heading">
+      <div><span className="section-code">Across authorized work</span><h2 id="budget-overview-title">Spend &amp; budget headroom</h2></div>
+      <button type="button" className="button button-secondary" onClick={onRefresh}>Refresh budgets</button>
+    </header>
+    {overview.state !== 'current' ? <p className="budget-overview-notice" role="status">{overview.reason}</p> : <>
+      <p className="budget-overview-scope">
+        Snapshot-limited totals · {snapshot.corp.name} · {overview.rows.length} authorized missions.<br />
+        No time filter; includes completed work returned in this snapshot. Received <time dateTime={stamp.receivedAt!}>{new Date(stamp.receivedAt!).toLocaleString()}</time> (browser time).
+        {' '}Refresh after 60 seconds or when access changes.
+      </p>
+      <p className="budget-overview-boundary">Each mission keeps its own ceiling. These totals are not a shared pool or permission to spend.</p>
+      {totals ? <dl className="budget-overview-metrics" data-testid="budget-overview-totals">
+        <AuthorityValues label="Original authority" value={totals.original} costLabel="authorized" />
+        <AuthorityValues label="Current authority" value={totals.current} costLabel="authorized" />
+        <AuthorityValues label="Recorded consumption" value={totals.consumed} costLabel="reported cost" />
+        <AuthorityValues label="Ledger remainder" value={totals.remaining} costLabel="after reported cost" />
+      </dl> : null}
+      <p className="budget-overview-notice" data-testid="budget-cost-provenance">
+        Measured and estimated cost are unavailable: the ledger does not record pricing provenance.
+        {' '}{unpriced} runs have unpriced token usage; {unreported} have no recorded usage or price.
+        {' '}Zero reported cost is not evidence of free work. The dollar remainder may overstate headroom when costs are missing.
+      </p>
+      {incomplete ? <p className="budget-overview-notice" role="status">
+        Some usage or run history is missing or invalid. Withheld totals and remainders are unavailable, not zero.
+        {overview.unattributedRuns > 0 ? ` ${overview.unattributedRuns} returned runs could not be attributed to an authorized mission.` : ''}
+      </p> : null}
+      {missingDecisions > 0 ? <p className="budget-overview-notice">{missingDecisions} revised mission ceilings have no matching approval receipt in this snapshot. Inspect their budget records before making a decision.</p> : null}
+      <div className="budget-overview-attention" aria-label="Budget decisions and recovery">
+        <strong>{pending.length} budget requests need a decision · {suspended.length} missions have recorded suspensions</strong>
+        {pending.length ? <ul>{pending.map(({ row, revision }) => {
+          const requested = budgetAuthority(revision.proposed_budget_tokens, revision.proposed_budget_cost_microusd)
+          return <li key={revision.id}>
+          <button type="button" onClick={() => open({ kind: 'revision', missionId: row.mission.id, revisionId: revision.id })}>
+            {row.mission.title} · inspect pending revision {revision.version}
+          </button>
+          <span>Requested: {formatBudgetTokens(requested.tokens)} · {formatBudgetMoney(requested.cost)}. Not yet authorized.</span>
+        </li>})}</ul> : <p>No pending budget requests in this snapshot.</p>}
+        <p>Auditor-led extension and audit status are unavailable in the current server. Existing manual revision and recovery records remain the source of authority.</p>
+      </div>
+      {overview.rows.length ? <details className="budget-overview-missions">
+        <summary>Inspect {overview.rows.length} mission budgets</summary>
+        <ul>{overview.rows.map((row) => <li key={row.mission.id} data-budget-overview-mission={row.mission.id}>
+          <header><div><h3>{row.mission.title}</h3><span>{row.mission.status.replaceAll('_', ' ')}</span></div>
+            <button type="button" className="button button-secondary" onClick={() => open({ kind: 'budget', missionId: row.mission.id })}>Open mission budget</button>
+          </header>
+          <dl className="budget-overview-metrics">
+            <AuthorityValues label="Original" value={row.original} costLabel="authorized" />
+            <AuthorityValues label="Current" value={row.current} costLabel="authorized" />
+            <AuthorityValues label="Consumed" value={row.consumed} costLabel="reported cost" />
+            <AuthorityValues label="Remaining" value={row.remaining} costLabel="after reported cost" />
+          </dl>
+          <p>{row.runCount} unique runs · {row.workerCount} participating agents · {row.resumedRunCount} resumed runs.
+            {' '}Retries, worker and auditor usage are counted once from persisted run totals.</p>
+          <p>{row.reportedCostRuns} runs report a positive cost · {row.unpricedRuns} unpriced · {row.unreportedRuns} without reported usage.</p>
+          {row.missingHistory || row.invalidUsage ? <p className="budget-overview-notice">Usage history is incomplete or invalid; the recorded subtotal is not proof of total consumption.</p> : null}
+          {row.currentDecisionMissing ? <p className="budget-overview-notice">The server reports a revised ceiling, but its matching approval receipt is unavailable in this snapshot.</p> : null}
+          <div className="budget-overview-links">
+            {row.revisions.map((revision) => <button type="button" key={revision.id}
+              onClick={() => open({ kind: 'revision', missionId: row.mission.id, revisionId: revision.id })}>
+              Revision {revision.version} · {revision.status}
+            </button>)}
+            {row.suspendedRunIds.map((runId) => <button type="button" key={runId}
+              onClick={() => open({ kind: 'suspension', missionId: row.mission.id, runId })}>
+              Inspect suspension {runId.slice(0, 8)} &amp; existing recovery controls
+            </button>)}
+          </div>
+        </li>)}</ul>
+      </details> : <p>No missions are available in this authorized snapshot.</p>}
+    </>}
+  </section>
+}
