+  --paper: var(--theme-raised);
+  --paper-light: var(--theme-surface);
+  --paper-deep: var(--theme-canvas);
+  --surface: var(--theme-surface);
+  --ink: var(--theme-text);
+  --ink-soft: var(--theme-muted);
+  --cobalt: var(--theme-accent);
+  --cobalt-dark: var(--theme-accent-hover);
