+  --line: var(--theme-border);
+  --shadow: var(--theme-shadow);
+  --arcade-accent: var(--theme-accent);
+  --arcade-purple: var(--theme-accent-surface);
+  --arcade-violet: var(--theme-raised);
+  --arcade-screen: var(--theme-surface);
+  --focus-ring: var(--theme-focus);
+  --surface-hover: var(--theme-hover);
