+  --theme-accent: #ff9fb3;
+  --theme-accent-hover: #ffc0ce;
+  --theme-accent-surface: #3e2935;
+  --theme-on-accent: #26151c;
+  --theme-focus: #ffc0ce;
+  --theme-success: #99e5b5;
+  --theme-success-surface: #173329;
+  --theme-warning: #f1ce80;
+  --theme-warning-surface: #392e1b;
+  --theme-danger: #ffabb7;
+  --theme-danger-surface: #401f2b;
+  --theme-info: #a6d5ff;
+  --theme-info-surface: #1c2e41;
+  --theme-shadow: 0 2px 5px rgb(0 0 0 / 28%), 0 10px 30px rgb(0 0 0 / 20%);
+  --theme-scrim: rgb(0 0 0 / 70%);
+}
+
+:root { background: var(--theme-canvas); }
+body { color: var(--theme-text); background: var(--theme-canvas) !important; }
+.app-shell :is(input, select, textarea) { accent-color: var(--theme-accent); }
+.app-shell .brand-mark { background: #131313; color: #ffffff; }
+.app-shell .brand-e { color: #ffffff; }
+.app-shell :is(.button-danger, .emergency-stop) {
+  color: var(--theme-on-accent) !important;
+  background: var(--theme-danger) !important;
+}
+.app-shell .journey-complete > span { color: var(--theme-on-accent); }
+.app-shell .world-inspector-scrim { background: var(--theme-scrim); }
+.app-shell .world-inspector { color: var(--theme-text); background: var(--theme-surface); }
+.app-shell [hidden] { display: none !important; }
+
+.presentation-preferences {
+  display: flex; flex-wrap: wrap; gap: 0.5rem 0.75rem;
+  min-width: 0; max-width: 100%; margin: 0; padding: 0; border: 0;
