+.presentation-executive .topbar { flex-wrap: wrap; }
+.presentation-executive .operator-console { flex-wrap: wrap; }
+@media (max-width: 440px) {
+  .presentation-preferences { width: 100%; }
+  .presentation-preferences label { flex: 1 1 100px; }
+}
