index 00000000..adbc7b89
--- /dev/null
+++ b/apps/web/src/HistoryPanel.test.mjs
@@ -0,0 +1,179 @@
+import assert from 'node:assert/strict'
+import { readFile } from 'node:fs/promises'
+import test from 'node:test'
+import * as jsxRuntime from 'react/jsx-runtime'
+import { renderToStaticMarkup } from 'react-dom/server'
+import ts from 'typescript'
+import * as history from './history.ts'
+import { elements, renderHooks } from './testSupport/renderHooks.mjs'
+
+const compiled = ts.transpileModule(await readFile(new URL('./HistoryPanel.tsx', import.meta.url), 'utf8'), {
+  compilerOptions: { target: ts.ScriptTarget.ES2023, module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.ReactJSX },
+}).outputText
+const id = (n) => `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`
+const text = (node) => Array.isArray(node) ? node.map(text).join('')
+  : node && typeof node === 'object' ? text(node.props?.children) : node == null ? '' : String(node)
+const tick = () => new Promise((resolve) => setImmediate(resolve))
+function fixture() {
+  const hooks = renderHooks(), calls = [], navigations = [], focus = [], exports = {}
+  const imports = { react: hooks.react, 'react/jsx-runtime': jsxRuntime, './history': history, './HistoryPanel.css': {} }
+  new Function('require', 'exports', compiled)((name) => {
+    assert.ok(Object.hasOwn(imports, name), name); return imports[name]
+  }, exports)
+  let props = { corpId: id(1), corpName: 'Private Corp', actorId: id(2), actorName: 'Reviewer',
+    rooms: [{ id: id(3), name: 'Engineering' }], actors: [{ id: id(2), name: 'Reviewer' }],
+    revision: 'access-1', connected: true, onNavigate: (link) => navigations.push(link),
+    api(path, init) {
+      let resolve, reject
+      const promise = new Promise((yes, no) => { resolve = yes; reject = no })
+      calls.push({ path, init, resolve, reject }); return promise
+    } }
+  const render = (next = props) => {
+    props = next
+    hooks.render(() => exports.HistoryPanel(props))
+    const heading = elements(hooks.value, (n) => n.type === 'h3')[0]
+    heading.props.ref.current = { focus: () => focus.push(text(heading)) }
+    return hooks.value
+  }
+  const button = (label) => {
+    const matches = elements(hooks.value, (n) => n.type === 'button' && text(n) === label)
+    assert.equal(matches.length, 1, label); return matches[0]
+  }
+  const control = (label) => {
+    const parent = elements(hooks.value, (n) => n.type === 'label' && text(n).startsWith(label))[0]
+    assert.ok(parent, label)
+    return elements(parent, (n) => n.type === 'input' || n.type === 'select')[0]
+  }
+  const answer = (index, { count = 25, start = 80, next = 'abcd', cause = null, link = true } = {}) => {
+    const url = new URL(calls[index].path, 'http://fixture.invalid'), filters = history.emptyHistoryFilters()
+    for (const key of Object.keys(filters)) filters[key] = url.searchParams.get(key) ?? filters[key]
+    calls[index].resolve({ corp_id: url.pathname.split('/')[3], actor_id: url.searchParams.get('actor_id'),
+      filters, page_size: 25, observed_at: '2026-09-29T15:00:00Z', next_cursor: next,
+      entries: Array.from({ length: count }, (_, i) => ({ id: id(start - i), kind: filters.kind,
+        room_id: id(3), title: '<script>never execute</script>', summary: 'Safe static summary', status: 'run.completed',
+        actor_id: id(2), actor_name: 'Reviewer', created_at: '2026-09-29T12:00:00Z', seq: String(start - i),
+        mission_id: link ? id(4) : null, task_id: link ? id(5) : null, run_id: link ? id(6) : null, cause_id: cause })) })
+  }
+  render()
+  return { hooks, calls, navigations, focus, render, button, control, answer,
+    submit() { elements(hooks.value, (n) => n.type === 'form')[0].props.onSubmit({ preventDefault() {} }); render() },
+    get props() { return props }, get tree() { return hooks.value }, get html() { return renderToStaticMarkup(hooks.value) },
+    async flush() { await tick(); render() }, unmount: hooks.unmount }
+}
+
+test('history shows loading, applied scope, safe details and explicit partial-history limits', async () => {
+  const f = fixture()
+  try {
+    assert.match(f.html, /Loading authorized history/)
+    assert.match(f.html, /Private Corp.*Reviewer/)
+    assert.match(f.html, /not a complete export or a count of all work/)
+    assert.match(f.html, /Events are ordered by journal sequence/)
+    assert.equal(f.button('Next page').props.disabled, true)
+    f.answer(0); await f.flush()
+    assert.match(f.html, /25 records on this page/)
+    assert.match(f.html, /&lt;script&gt;never execute&lt;\/script&gt;/)
+    assert.doesNotMatch(f.html, /<script>|Loading authorized/)
+    assert.equal(elements(f.tree, (n) => n.props?.['data-history-id']).length, 25)
+    assert.equal(f.focus.length, 0, 'initial/background loading must not steal focus')
+    elements(f.tree, (n) => n.type === 'button' && text(n) === 'Open exact run')[0].props.onClick()
+    assert.deepEqual(f.navigations, [{ kind: 'run', id: id(6) }])
+  } finally { f.unmount() }
+})
+
+test('next/previous use server cursors and preserve the applied query until explicit refresh', async () => {
+  const f = fixture()
+  try {
+    f.answer(0); await f.flush()
+    f.button('Next page').props.onClick(); f.render()
+    assert.match(f.calls[1].path, /cursor=abcd/)
+    assert.doesNotMatch(f.html, /25 records on this page/)
+    f.answer(1, { count: 2, start: 55, next: null }); await f.flush()
+    assert.match(f.html, /page 2/)
+    assert.match(f.html, /2 records on this page/)
+    assert.equal(f.button('Next page').props.disabled, true)
+    assert.equal(f.focus.length, 1)
+    f.button('Previous page').props.onClick(); f.render()
+    assert.doesNotMatch(f.calls[2].path, /cursor=/)
+    f.answer(2); await f.flush()
+    assert.match(f.html, /page 1/)
+    f.button('Refresh history').props.onClick(); f.render()
+    assert.doesNotMatch(f.calls[3].path, /cursor=/)
+    assert.match(f.html, /Search refreshed from the first page/)
+  } finally { f.unmount() }
+})
+
+test('draft input does not silently change applied filters; invalid IDs make no request', async () => {
+  const f = fixture()
+  try {
+    f.answer(0); await f.flush()
+    f.control('Search titles').props.onChange({ target: { value: 'literal %_' } }); f.render()
+    assert.equal(f.calls.length, 1)
+    const applied = elements(f.tree, (n) => n.props?.['data-testid'] === 'history-applied')[0]
+    assert.doesNotMatch(text(applied), /literal/)
+    f.control('Mission ID').props.onChange({ target: { value: 'invalid-id' } }); f.render(); f.submit()
+    assert.match(f.html, /Use valid IDs/)
+    assert.equal(f.calls.length, 1)
+    f.control('Mission ID').props.onChange({ target: { value: id(4) } }); f.render(); f.submit()
+    assert.equal(new URL(f.calls[1].path, 'http://fixture.invalid').searchParams.get('search'), 'literal %_')
+    assert.match(f.html, /literal %_/)
+    assert.equal(f.calls[0].init.signal.aborted, true)
+    f.answer(1, { count: 0, next: null }); await f.flush()
+    assert.match(f.html, /No authorized records match/)
+    assert.match(f.html, /not a statement about hidden or retained history/)
+    assert.equal(f.button('Next page').props.disabled, true)
+    f.button('Clear filters').props.onClick(); f.render()
+    assert.equal(new URL(f.calls[2].path, 'http://fixture.invalid').searchParams.has('mission_id'), false)
+  } finally { f.unmount() }
+})
+
+test('unknown well-formed event filters show a form error without replacing authorized results or requesting the server', async () => {
+  const f = fixture()
+  try {
+    f.answer(0); await f.flush()
+    f.control('Event type').props.onChange({ target: { value: 'not.a.real.event' } }); f.render(); f.submit()
+    assert.equal(f.calls.length, 1)
+    assert.match(f.html, /supported status/u)
+    assert.match(f.html, /25 records on this page/u)
+    assert.doesNotMatch(f.html, /History is unavailable|Loading authorized history/u)
+    const applied = elements(f.tree, (n) => n.props?.['data-testid'] === 'history-applied')[0]
+    assert.doesNotMatch(text(applied), /not\.a\.real\.event/u)
+    f.control('Event type').props.onChange({ target: { value: 'other' } }); f.render(); f.submit()
+    assert.equal(new URL(f.calls[1].path, 'http://fixture.invalid').searchParams.get('status'), 'other')
+  } finally { f.unmount() }
+})
+
+test('causal navigation clears incompatible filters and names the exact event with no payload rendering', async () => {
+  const f = fixture()
+  try {
+    f.answer(0, { count: 1, next: null, cause: id(19), link: false }); await f.flush()
+    assert.match(f.html, /No authorized work link recorded/)
+    f.button('Open causal event').props.onClick(); f.render()
+    const params = new URL(f.calls[1].path, 'http://fixture.invalid').searchParams
+    assert.equal(params.get('record_id'), id(19))
+    assert.equal(params.get('kind'), 'event')
+    for (const name of ['room_id', 'mission_id', 'attributed_actor_id', 'status']) assert.equal(params.has(name), false)
+    assert.match(f.html, /Opened the exact causal event.*Other filters were cleared/)
+    assert.match(f.html, /Exact event/)
+  } finally { f.unmount() }
+})
+
+test('revocation, disconnect and stale responses cannot retain or substitute history rows', async () => {
+  const f = fixture()
+  try {
+    f.answer(0); await f.flush()
+    f.render({ ...f.props, revision: 'access-revoked', rooms: [] })
+    assert.doesNotMatch(f.html, /25 records on this page/)
+    assert.equal(f.calls[0].init.signal.aborted, true)
+    f.calls[1].reject(new Error('database password must never render')); await f.flush()
+    assert.match(f.html, /History is unavailable/)
+    assert.doesNotMatch(f.html, /password/)
+    f.render({ ...f.props, connected: false })
+    assert.match(f.html, /Live updates are disconnected or stale/)
+    assert.match(f.html, /Loading authorized history/)
+    f.render({ ...f.props, connected: true })
+    f.answer(2); await f.flush()
+    assert.doesNotMatch(f.html, /25 records on this page/)
+    f.answer(3, { count: 0, next: null }); await f.flush()
+    assert.match(f.html, /No authorized records match/)
+  } finally { f.unmount() }
+})
diff --git a/apps/web/src/HistoryPanel.tsx b/apps/web/src/HistoryPanel.tsx
new file mode 100644
index 00000000..3298017b
--- /dev/null
+++ b/apps/web/src/HistoryPanel.tsx
@@ -0,0 +1,223 @@
+import { useEffect, useMemo, useRef, useState } from 'react'
+import type { FormEvent } from 'react'
+import type { WorkLink } from './workflowContext'
+import {
+  causalHistoryFilters, emptyHistoryFilters, HISTORY_ENTITY_STATUSES, HISTORY_KINDS,
+  HISTORY_PAGE_SIZE, historyEntryLink, historyPosition, normalizeHistoryFilters, requestHistoryPage,
+} from './history'
+import type { HistoryFilters, HistoryKind, HistoryLoad, HistoryPosition } from './history'
+import './HistoryPanel.css'
+
+type Choice = { id: string; name: string }
+type Props = {
+  corpId: string
+  corpName: string
+  actorId: string
+  actorName: string
+  rooms: readonly Choice[]
+  actors: readonly Choice[]
+  initialKind?: HistoryKind
+  revision: string
+  connected: boolean
+  api: <T>(path: string, init?: RequestInit) => Promise<T>
+  onNavigate: (link: WorkLink) => void
+}
+type PageStart = { cursor: string | null; after: HistoryPosition | null }
+const FIRST_PAGE: PageStart = { cursor: null, after: null }
+const nameFor = (choices: readonly Choice[], id: string | null) =>
+  id === null ? 'Any' : choices.find((choice) => choice.id === id)?.name ?? id
+const date = (value: string) => new Date(value).toLocaleString()
+
+export function HistoryPanel({
+  corpId, corpName, actorId, actorName, rooms, actors, initialKind = 'event',
+  revision, connected, api, onNavigate,
+}: Props) {
+  const [draft, setDraft] = useState<HistoryFilters>(() => emptyHistoryFilters(initialKind))
+  const [applied, setApplied] = useState<HistoryFilters>(() => emptyHistoryFilters(initialKind))
+  const [trail, setTrail] = useState<PageStart[]>([FIRST_PAGE])
+  const [refresh, setRefresh] = useState(0)
+  const [load, setLoad] = useState<HistoryLoad | null>(null)
+  const [formError, setFormError] = useState<string | null>(null)
+  const [notice, setNotice] = useState('')
+  const results = useRef<HTMLHeadingElement>(null)
+  const focusResults = useRef(false)
+  const start = trail[trail.length - 1]
+  const request = useMemo(() => ({
+    corpId, actorId, filters: applied, cursor: start.cursor, after: start.after,
+    pageSize: HISTORY_PAGE_SIZE,
+  }), [corpId, actorId, applied, start])
+  // The authorization revision changes with viewer/room access. Invalidate
+  // immediately, without restarting a search for every streamed runner event.
+  const key = JSON.stringify([request, refresh, revision, connected])
+  const current = load?.key === key ? load : null
+  const page = current?.status === 'ready' ? current.page : null
+  useEffect(() => requestHistoryPage(request, key, api, setLoad), [request, key, api])
+  useEffect(() => {
+    if (current?.status === 'loading' || !current || !focusResults.current) return
+    focusResults.current = false
+    results.current?.focus()
+  }, [current])
+  const apply = (filters: HistoryFilters, message = '') => {
+    const normalized = normalizeHistoryFilters(filters)
+    if (!normalized) {
+      setFormError('Use valid IDs, a supported status or event type and at most 160 search characters without control characters.')
+      return
+    }
+    setFormError(null)
+    setDraft(normalized)
+    setApplied(normalized)
+    setTrail([FIRST_PAGE])
+    setRefresh((value) => value + 1)
+    setNotice(message)
+    focusResults.current = true
+  }
+  const submit = (event: FormEvent) => { event.preventDefault(); apply(draft) }
+  return (
+    <section className="history-browser" aria-label="Searchable work history" data-testid="history-browser">
+      <p className="history-scope">
+        Corp: <strong>{corpName}</strong> · Viewer: <strong>{actorName}</strong>.
+        Only records currently authorized for this viewer are returned.
+      </p>
+      <form className="history-filters" onSubmit={submit}>
+        <label>Record type
+          <select value={draft.kind} onChange={(event) => setDraft({
+            ...draft, kind: event.target.value as HistoryKind, status: null, record_id: null,
+          })}>
+            {HISTORY_KINDS.map((kind) => <option key={kind} value={kind}>{kind[0].toUpperCase() + kind.slice(1)} history</option>)}
+          </select>
+        </label>
+        <label>Search titles, IDs or status
+          <input type="search" maxLength={320} value={draft.search}
+            onChange={(event) => setDraft({ ...draft, search: event.target.value })}
+            placeholder="Literal text; payloads are never searched" />
+        </label>
+        <label>Room
+          <select value={draft.room_id ?? ''} onChange={(event) => setDraft({ ...draft, room_id: event.target.value || null })}>
+            <option value="">All authorized rooms</option>
+            {draft.room_id && !rooms.some((room) => room.id === draft.room_id)
+              ? <option value={draft.room_id}>Unavailable room</option> : null}
+            {rooms.map((room) => <option key={room.id} value={room.id}>{room.name}</option>)}
+          </select>
+        </label>
+        <label>Attributed actor
+          <select value={draft.attributed_actor_id ?? ''}
+            onChange={(event) => setDraft({ ...draft, attributed_actor_id: event.target.value || null })}>
+            <option value="">Any recorded actor</option>
+            {draft.attributed_actor_id && !actors.some((actor) => actor.id === draft.attributed_actor_id)
+              ? <option value={draft.attributed_actor_id}>Unavailable actor</option> : null}
+            {actors.map((actor) => <option key={actor.id} value={actor.id}>{actor.name}</option>)}
+          </select>
+        </label>
+        <label>{draft.kind === 'event' ? 'Event type' : 'Status'}
+          {draft.kind === 'event' ? (
+            <input value={draft.status ?? ''} maxLength={96} placeholder="Any; e.g. run.started"
+              onChange={(event) => setDraft({ ...draft, status: event.target.value || null })} />
+          ) : (
+            <select value={draft.status ?? ''} onChange={(event) => setDraft({ ...draft, status: event.target.value || null })}>
+              <option value="">Any status</option>
+              {HISTORY_ENTITY_STATUSES[draft.kind].map((status) => <option key={status} value={status}>{status.replaceAll('_', ' ')}</option>)}
+            </select>
+          )}
+        </label>
+        <label>Mission ID (optional)
+          <input value={draft.mission_id ?? ''} maxLength={36} placeholder="Exact mission UUID"
+            onChange={(event) => setDraft({ ...draft, mission_id: event.target.value || null })} />
+        </label>
+        <div className="history-controls">
+          <button className="button button-primary" type="submit">Apply filters</button>
+          <button className="button button-secondary" type="button"
+            onClick={() => apply(emptyHistoryFilters(applied.kind))}>Clear filters</button>
+        </div>
+      </form>
+      {formError ? <p role="alert">{formError}</p> : null}
+      <div className="history-applied" data-testid="history-applied">
+        <strong>Applied filters</strong>
+        <dl>
+          <div><dt>Kind</dt><dd>{applied.kind}</dd></div>
+          <div><dt>Search</dt><dd>{applied.search || 'Any'}</dd></div>
+          <div><dt>Room</dt><dd>{nameFor(rooms, applied.room_id)}</dd></div>
+          <div><dt>Actor</dt><dd>{nameFor(actors, applied.attributed_actor_id)}</dd></div>
+          <div><dt>Status / event type</dt><dd>{applied.status ?? 'Any'}</dd></div>
+          <div><dt>Mission</dt><dd>{applied.mission_id ?? 'Any'}</dd></div>
+          {applied.record_id ? <div><dt>Exact event</dt><dd>{applied.record_id}</dd></div> : null}
+        </dl>
+      </div>
+      <p className="history-limit" data-testid="history-limits">
+        This is a live, paged view, not a complete export or a count of all work.
+        {applied.kind === 'event'
+          ? ' Events are ordered by journal sequence, descending; gaps do not imply missing authorized records.'
+          : ' Records are ordered by creation time, then ID, descending.'}
+        {' '}New commits, changing status or access can change earlier pages. Refresh from the beginning for late records.
+        Summaries exclude raw payloads; actor attribution does not establish approval or accepted completion.
+      </p>
+      {!connected ? <p role="status">Live updates are disconnected or stale. Each history request still checks current access; refresh to retry.</p> : null}
+      {notice ? <p role="status">{notice}</p> : null}
+      <div className="history-results-heading">
+        <h3 ref={results} tabIndex={-1}>History results · page {trail.length}</h3>
+        <button className="button button-secondary" type="button"
+          onClick={() => apply(applied, 'Search refreshed from the first page.')}>Refresh history</button>
+      </div>
+      {!current || current.status === 'loading' ? <p role="status" aria-live="polite">Loading authorized history…</p> : null}
+      {current?.status === 'error' ? <p role="alert">{current.message}</p> : null}
+      {page ? (
+        <>
+          <p role="status">{page.entries.length} record{page.entries.length === 1 ? '' : 's'} on this page.
+            {' '}Search started <time dateTime={page.observed_at}>{date(page.observed_at)}</time>.
+          </p>
+          {page.entries.length === 0 ? <p className="empty-state">No authorized records match the applied filters. This is not a statement about hidden or retained history.</p> : null}
+          <ol className="history-entries" data-testid="history-entries">
+            {page.entries.map((record) => {
+              const link = historyEntryLink(record)
+              return (
+                <li key={record.id} data-history-id={record.id} data-history-kind={record.kind}>
+                  <article>
+                    <div className="history-entry-heading">
+                      <h4>{record.title || 'Untitled ' + record.kind}</h4>
+                      <span className="history-record-status">{record.status.replaceAll('_', ' ')}</span>
+                    </div>
+                    <p>{record.summary}</p>
+                    <p className="history-attribution">
+                      {record.actor_name ?? (record.actor_id ? 'Recorded actor' : 'No recorded actor')}
+                      {record.actor_id ? ' · ' + record.actor_id : ''}
+                      {' · '}<time dateTime={record.created_at}>{date(record.created_at)}</time>
+                    </p>
+                    <details>
+                      <summary>Record details</summary>
+                      <dl>
+                        <div><dt>ID</dt><dd>{record.id}</dd></div>
+                        {record.seq ? <div><dt>Journal sequence</dt><dd>{record.seq}</dd></div> : null}
+                        <div><dt>Room</dt><dd>{record.room_id ? nameFor(rooms, record.room_id) : 'Corp record'}</dd></div>
+                        {record.mission_id ? <div><dt>Mission</dt><dd>{record.mission_id}</dd></div> : null}
+                        {record.task_id ? <div><dt>Task</dt><dd>{record.task_id}</dd></div> : null}
+                        {record.run_id ? <div><dt>Run</dt><dd>{record.run_id}</dd></div> : null}
+                      </dl>
+                    </details>
+                    <div className="history-controls">
+                      {link ? <button className="button button-secondary" type="button"
+                        onClick={() => onNavigate(link)}>Open exact {link.kind}</button>
+                        : <span>No authorized work link recorded.</span>}
+                      {record.cause_id ? <button className="button button-secondary" type="button"
+                        onClick={() => apply(causalHistoryFilters(record.cause_id!),
+                          'Opened the exact causal event. Other filters were cleared; the server rechecks access.')}>Open causal event</button> : null}
+                    </div>
+                  </article>
+                </li>
+              )
+            })}
+          </ol>
+        </>
+      ) : null}
+      <nav className="history-controls" aria-label="History pages">
+        <button className="button button-secondary" type="button" disabled={trail.length === 1 || !page}
+          onClick={() => { setTrail(trail.slice(0, -1)); focusResults.current = true }}>Previous page</button>
+        <button className="button button-secondary" type="button" disabled={!page?.next_cursor}
+          onClick={() => {
+            if (!page?.next_cursor || !page.entries.length) return
+            setTrail([...trail, { cursor: page.next_cursor, after: historyPosition(page.entries[page.entries.length - 1]) }])
+            focusResults.current = true
+          }}>Next page</button>
+        {page && !page.next_cursor ? <span>End of the currently available matching pages. Refresh for changes.</span> : null}
+      </nav>
+    </section>
+  )
+}
