+    'https://fixture:fixture@example.invalid/path',
+    'ghp_' + 'x'.repeat(24), '-----BEGIN PRIVATE KEY-----', 'fixture-key-body', '-----END PRIVATE KEY-----',
+    'visible\u001b[31m\u202eend', 'after key block',
