+        assert_eq!(p.filters.search, "LITERAL %_");
+        assert_eq!(p.entries.len(), 3);
+        for text in ["private", "literal%_", "nonexistent"] {
+            assert!(
+                page(
+                    &f,
+                    HistoryFilters {
+                        search: text.into(),
+                        ..kind_filters(kind)
+                    },
+                    10,
+                    None
+                )
+                .await?
+                .entries
+                .is_empty()
+            );
+        }
+    }
+    let r = &records[1];
+    let e = page(
